// Pre-flight checklist: validate config BEFORE any API / LLM call
const c = Object.assign({}, $input.first().json);
const warnings = [];
const isBlank = function (v) {
  return v === undefined || v === null || String(v).trim() === '';
};

const sources = {
  slack: c.enableSlack === true,
  gmail: c.enableGmail === true,
  calendar: c.enableCalendar === true,
};

// Misconfigured sources are skipped (warn), not crashed
if (sources.slack && isBlank(c.slackSearchQuery)) {
  sources.slack = false;
  warnings.push('Slack skipped: slackSearchQuery is not configured');
}
if (!(Number(c.lookbackHours) > 0 && Number(c.lookbackHours) <= 168)) {
  warnings.push('lookbackHours invalid - defaulting to 24');
  c.lookbackHours = 24;
}
if (!(Number(c.gmailMaxResults) > 0 && Number(c.gmailMaxResults) <= 100)) {
  warnings.push('gmailMaxResults invalid - defaulting to 25');
  c.gmailMaxResults = 25;
}
Object.keys(sources).forEach(function (k) {
  if (!sources[k]) warnings.push(k + ' disabled - will be skipped');
});

// Hard failure (fires the Error Workflow): nothing to digest
if (!sources.slack && !sources.gmail && !sources.calendar) {
  throw new Error('Guardrail failed: all sources are disabled - nothing to digest');
}

c.sources = sources;
c.warnings = warnings;
return [{ json: c }];

// Execution context + previous-run state (for [New] vs [Recurring] delta tracking)
const g = $input.first().json;
const store = $getWorkflowStaticData('global');
const now = new Date();
const out = Object.assign({}, g, {
  sessionId: 'digest-' + now.getTime() + '-' + Math.random().toString(36).slice(2, 8),
  runTimestamp: now.toISOString(),
  runDate: $now.setZone(g.timezone || 'UTC').toFormat('cccc, dd LLL yyyy'),
  lastRunAt: store.lastRunAt || null,
  previousDigest: store.previousDigest || '',
});
return [{ json: out }];

// Input contract: normalize Slack results into one compact item (handles empty + failed fetch)
const items = $input.all().map(function (i) { return i.json; }).filter(function (j) { return Object.keys(j).length > 0; });
const failed = items.filter(function (j) { return j.error; });
// Feedback-loop guard: skip bot posts and previous digests so the agent never re-ingests its own output
const isDigestEcho = function (m) {
  const t = String(m.content || '');
  return m.is_author_bot === true || t.indexOf('Daily Digest for') !== -1 || t.indexOf('_Session ') !== -1;
};
const records = items.filter(function (j) { return !j.error && !isDigestEcho(j); }).slice(0, 30).map(function (m) {
  return { channel: m.channel_name, author: m.author_name, text: String(m.content || '').slice(0, 400), link: m.permalink };
});
const errMsg = failed.length ? String((failed[0].error && failed[0].error.message) || failed[0].error) : null;
return [{ json: { source: 'Slack', fetchError: errMsg, count: records.length, records: JSON.stringify(records) } }];

// Output contract: { source, status: ok|unavailable|disabled, summary, note }
const g = $('State Management').first().json;
if (!g.sources.slack) return [{ json: { source: 'Slack', status: 'disabled', summary: '', note: 'disabled or misconfigured in Orchestrator' } }];
let prep = null;
try { prep = $('Prep Slack Data').first().json; } catch (e) { prep = null; }
const out = $input.first().json;
if (prep && prep.fetchError) return [{ json: { source: 'Slack', status: 'unavailable', summary: '', note: 'fetch failed: ' + prep.fetchError } }];
if (!out.output) return [{ json: { source: 'Slack', status: 'unavailable', summary: '', note: 'agent failed: ' + JSON.stringify(out.error || 'no output').slice(0, 200) } }];
return [{ json: { source: 'Slack', status: 'ok', summary: out.output, note: (prep ? prep.count : 0) + ' messages analysed' } }];

// Input contract: normalize emails into one compact item (handles empty + failed fetch)
const items = $input.all().map(function (i) { return i.json; }).filter(function (j) { return Object.keys(j).length > 0; });
const failed = items.filter(function (j) { return j.error; });
const records = items.filter(function (j) { return !j.error; }).map(function (m) {
  return { from: m.From, subject: m.Subject, snippet: String(m.snippet || '').slice(0, 300), unread: Array.isArray(m.labels) && m.labels.some(function (l) { return l.id === 'UNREAD'; }) };
});
const errMsg = failed.length ? String((failed[0].error && failed[0].error.message) || failed[0].error) : null;
return [{ json: { source: 'Gmail', fetchError: errMsg, count: records.length, records: JSON.stringify(records) } }];

// Output contract: { source, status: ok|unavailable|disabled, summary, note }
const g = $('State Management').first().json;
if (!g.sources.gmail) return [{ json: { source: 'Gmail', status: 'disabled', summary: '', note: 'disabled or misconfigured in Orchestrator' } }];
let prep = null;
try { prep = $('Prep Gmail Data').first().json; } catch (e) { prep = null; }
const out = $input.first().json;
if (prep && prep.fetchError) return [{ json: { source: 'Gmail', status: 'unavailable', summary: '', note: 'fetch failed: ' + prep.fetchError } }];
if (!out.output) return [{ json: { source: 'Gmail', status: 'unavailable', summary: '', note: 'agent failed: ' + JSON.stringify(out.error || 'no output').slice(0, 200) } }];
return [{ json: { source: 'Gmail', status: 'ok', summary: out.output, note: (prep ? prep.count : 0) + ' emails analysed' } }];

// Input contract: normalize events into one compact item (handles empty + failed fetch)
const items = $input.all().map(function (i) { return i.json; }).filter(function (j) { return Object.keys(j).length > 0; });
const failed = items.filter(function (j) { return j.error; });
const records = items.filter(function (j) { return !j.error; }).map(function (e) {
  return {
    title: e.summary,
    start: (e.start && (e.start.dateTime || e.start.date)) || '',
    end: (e.end && (e.end.dateTime || e.end.date)) || '',
    organizer: e.organizer && e.organizer.email,
    notes: String(e.description || '').slice(0, 300),
  };
});
const errMsg = failed.length ? String((failed[0].error && failed[0].error.message) || failed[0].error) : null;
return [{ json: { source: 'Calendar', fetchError: errMsg, count: records.length, records: JSON.stringify(records) } }];

// Output contract: { source, status: ok|unavailable|disabled, summary, note }
const g = $('State Management').first().json;
if (!g.sources.calendar) return [{ json: { source: 'Calendar', status: 'disabled', summary: '', note: 'disabled or misconfigured in Orchestrator' } }];
let prep = null;
try { prep = $('Prep Calendar Data').first().json; } catch (e) { prep = null; }
const out = $input.first().json;
if (prep && prep.fetchError) return [{ json: { source: 'Calendar', status: 'unavailable', summary: '', note: 'fetch failed: ' + prep.fetchError } }];
if (!out.output) return [{ json: { source: 'Calendar', status: 'unavailable', summary: '', note: 'agent failed: ' + JSON.stringify(out.error || 'no output').slice(0, 200) } }];
return [{ json: { source: 'Calendar', status: 'ok', summary: out.output, note: (prep ? prep.count : 0) + ' events analysed' } }];

// Fan-in: combine all agent outputs + previous run state into one synthesis payload
const results = $input.all().map(function (i) { return i.json; });
const st = $('State Management').first().json;
const ok = results.filter(function (r) { return r.status === 'ok'; });
const notOk = results.filter(function (r) { return r.status !== 'ok'; });
const sections = ok.map(function (r) { return '### ' + r.source + ' agent\n' + r.summary; }).join('\n\n');
return [{ json: {
  sections: sections || 'No source returned data.',
  availableSources: ok.map(function (r) { return r.source; }).join(', ') || 'none',
  unavailableSources: notOk.map(function (r) { return r.source + ' (' + r.status + (r.note ? ': ' + r.note : '') + ')'; }).join('; ') || 'none',
  previousDigest: st.previousDigest || 'No previous run on record - tag everything as [New].',
  okCount: ok.length,
  warnings: (st.warnings || []).join('; ') || 'none',
} }];

