// Output validation (empty / too long / missing sections) + persist state for next run
const out = $input.first().json;
const st = $('State Management').first().json;
const input = $('Build Synthesis Input').first().json;
const issues = [];
let digest = String(out.output || '').trim();
if (!digest) {
  issues.push('synthesizer returned empty output');
  digest = '*Source Status*\n- Synthesizer failed. Raw agent outputs below.\n\n' + input.sections;
}
['Top Priorities', 'Action Items', 'Schedule', 'FYI', 'Source Status'].forEach(function (s) {
  if (digest.toLowerCase().indexOf(s.toLowerCase()) === -1) issues.push('missing section: ' + s);
});
if (digest.length > 3500) {
  digest = digest.slice(0, 3500) + '\n...(truncated)';
  issues.push('digest truncated to 3500 chars');
}
const header = '*Daily Digest for ' + st.userName + '* | ' + st.runDate;
const footer = '\n\n_Session ' + st.sessionId + ' | Sources OK: ' + input.availableSources + ' | Unavailable: ' + input.unavailableSources +
  (issues.length ? ' | Validation: ' + issues.join(', ') : '') + '_';

// State management: store this digest so the next run can tag [New] vs [Recurring]
// (static data persists only for production / scheduled runs, not manual test runs)
const store = $getWorkflowStaticData('global');
store.previousDigest = digest;
store.lastRunAt = st.runTimestamp;
store.lastSessionId = st.sessionId;

return [{ json: { message: header + '\n\n' + digest + footer, issues: issues, sessionId: st.sessionId } }];
